DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_1','Honeycomb Commonwealth[NEWLINE]Worked-Plantation specialization and protected agrarian development[NEWLINE]Science or Culture through a developed economy[NEWLINE][NEWLINE]Settle useful Plantation resources, improve them, and actually assign citizens to work them. The capped city bonus is a reward for a functioning specialized settlement, not for owning every Plantation on the map.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_2','Scout resources and food together. Improve the relevant tiles and ensure a city has enough population to work them without starving its development. Foragers scout and reveal opportunities; they do not build or harvest Plantations.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_3','Review the worked assignments before ending the turn and construct Honey Exchanges where normal Market benefits and added Food are useful. Develop research infrastructure alongside the Production and Culture support.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_4','Protect the productive resource belt and keep assignments useful as specialists and new improvements compete for citizens. Respect the per-city cap: the fifth worked Plantation is a tile choice, not another uncapped UA tier.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_5','- A useful Plantation city gains steady flat Production and cultural support.[NEWLINE]- Exchanges add ordinary trade infrastructure and a modest Food/Gold contribution.[NEWLINE]- The resource plan is readable and does not require an active ability sequence.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_6','- Tiles must be eligible, owned, assigned and actually worked.[NEWLINE]- The per-city yield additions are capped and do not scale automatically with Era.[NEWLINE]- Pillage and assignment changes can reduce the next staged bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_7','- Threaten the actual productive Plantations and force citizens or workers away.[NEWLINE]- Pressure cities before enough improved tiles and population exist to support the specialization.[NEWLINE]- Use mobile raids against the resource belt rather than ignoring it in favour of a fortified centre.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_8','- Counting owned but unworked Plantations.[NEWLINE]- Treating a Forager as an improved Worker.[NEWLINE]- Expecting a midturn assignment change to rewrite the already staged payout immediately.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]RomanGladius Network: A good early Plantation site can provide practical output before an expensive Server population and staffing programme matures.[NEWLINE][NEWLINE]Pigeon Republic: A protected Plantation economy can operate without outgoing caravan capacity or an external destination.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast land units can reach resource tiles and force repeated repairs.[NEWLINE][NEWLINE]Jin: A mobile cavalry campaign can pressure the specialized countryside while the city needs those tiles worked.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_CIV_TEXT_10','The current implementation snapshots at owner end-turn for the next payout. Interturn pillage and reassignment can differ from a literal next-turn-start count; this documented timing limitation remains.');
