INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_BACKGROUND','Settle useful Plantation resources, improve them, and actually assign citizens to work them. The capped city bonus is a reward for a functioning specialized settlement, not for owning every Plantation on the map.');
