INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_BACKGROUND','Settle useful Plantation resources, improve them, and actually assign citizens to work them. The capped city bonus is a reward for a functioning specialized settlement, not for owning every Plantation on the map.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_HCC_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_STRATEGY','Settle useful Plantation resources, improve them, and actually assign citizens to work them. The capped city bonus is a reward for a functioning specialized settlement, not for owning every Plantation on the map.[NEWLINE][NEWLINE]Scout resources and food together. Improve the relevant tiles and ensure a city has enough population to work them without starving its development. Foragers scout and reveal opportunities; they do not build or harvest Plantations.[NEWLINE][NEWLINE]Review the worked assignments before ending the turn and construct Honey Exchanges where normal Market benefits and added Food are useful. Develop research infrastructure alongside the Production and Culture support.[NEWLINE][NEWLINE]Protect the productive resource belt and keep assignments useful as specialists and new improvements compete for citizens. Respect the per-city cap: the fifth worked Plantation is a tile choice, not another uncapped UA tier.');
