INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_TEXT_1','Honeycomb Commonwealth[NEWLINE]Worked-Plantation specialization and protected agrarian development[NEWLINE]Science or Culture through a developed economy[NEWLINE][NEWLINE]Settle useful Plantation resources, improve them, and actually assign citizens to work them. The capped city bonus is a reward for a functioning specialized settlement, not for owning every Plantation on the map.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_TEXT_2','Scout resources and food together. Improve the relevant tiles and ensure a city has enough population to work them without starving its development. Foragers scout and reveal opportunities; they do not build or harvest Plantations.[NEWLINE][NEWLINE]Review the worked assignments before ending the turn and construct Honey Exchanges where normal Market benefits and added Food are useful. Develop research infrastructure alongside the Production and Culture support.[NEWLINE][NEWLINE]Protect the productive resource belt and keep assignments useful as specialists and new improvements compete for citizens. Respect the per-city cap: the fifth worked Plantation is a tile choice, not another uncapped UA tier.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEHONEYCOMBCOMMONWEALTH_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]RomanGladius Network: A good early Plantation site can provide practical output before an expensive Server population and staffing programme matures.[NEWLINE][NEWLINE]Pigeon Republic: A protected Plantation economy can operate without outgoing caravan capacity or an external destination.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast land units can reach resource tiles and force repeated repairs.[NEWLINE][NEWLINE]Jin: A mobile cavalry campaign can pressure the specialized countryside while the city needs those tiles worked.');
